package com.oms.order.service;

import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;

class ReturnManagementQueryTest {
    RefundServiceTest f;ReturnQueryService query;ReturnQueryProjection projection;
    @BeforeAll static void start(){RefundServiceTest.start();}
    @BeforeEach void setup(){f=new RefundServiceTest();f.reset();for(String table:Arrays.asList("oms_return_query_number","oms_return_query_row","oms_return_query_dirty"))f.db.update("DELETE FROM "+table+" WHERE company_code IN ('VERIFY','OTHER')");projection=mock(ReturnQueryProjection.class);when(projection.refresh("VERIFY")).thenReturn(map("pending",0,"updating",false,"warning",""));query=new ReturnQueryService();query.repository=f.repo;query.projection=projection;}
    @AfterEach void clear(){for(String table:Arrays.asList("oms_return_query_number","oms_return_query_row","oms_return_query_dirty"))f.db.update("DELETE FROM "+table+" WHERE company_code IN ('VERIFY','OTHER')");f.clear();}
    long row(String company,String view,String group,String source,String kind,long owner,long qty,long accepted,long posted,String unit,int gift,int pending){return f.repo.insert("INSERT INTO oms_return_query_row(company_code,view_kind,group_key,source_key,part_key,owner_kind,owner_id,owner_sn,source_id,channel_id,order_id,order_sn,platform_tid,platform_oid,sku_sn,goods_name,unit,is_gift,quantity,accepted_quantity,posted_quantity,pending_count,expected_members,dispatched,waybill,return_sn,snapshot,create_time) VALUES (?,?,?,?,?,?,?,?,?,1,?,'SO_RETURN_QUERY','TID1','OID1','B','actual B',?,?,?,?,?,?,?,1,'RETURN_WAYBILL','THKX_QUERY','{}',NOW())",company,view,group,source,source,kind,owner,kind+owner,owner,f.order,unit,gift,qty,accepted,posted,pending,"TASK".equals(view)?1:2);}
    void indexNumber(String company,String view,String group,String kind,long owner,String type,String value){f.db.update("INSERT INTO oms_return_query_number(company_code,view_kind,group_key,owner_kind,owner_id,number_type,number_value) VALUES (?,?,?,?,?,?,?)",company,view,group,kind,owner,type,value);}
    Map<String,Object> list(String view,String number){return query.list("VERIFY",new HashMap<String,String>(){{put("view",view);put("number",number);}},false);}
    @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> value){return (List<Map<String,Object>>)value.get("rows");}
    @SuppressWarnings("unchecked") Map<String,Object> unit(Map<String,Object> r,int at){return ((List<Map<String,Object>>)r.get("units")).get(at);}
    void mixed(){row("VERIFY","PARCEL","P1","R1","REFUND",101,1,1,1,"件",0,0);row("VERIFY","PARCEL","P1","E1","EXCHANGE",201,1,1,1,"件",0,0);indexNumber("VERIFY","PARCEL","P1","REFUND",101,"OWNER","TK101");indexNumber("VERIFY","PARCEL","P1","EXCHANGE",201,"OWNER","HH201");}
    @Test void failedInteractionFilterPreservesWholeGroupAndAcceptedWarehouseState(){mixed();f.db.update("UPDATE oms_return_query_row SET warehouse_state='ACCEPTED',interaction_result='SUCCESS'");f.db.update("UPDATE oms_return_query_row SET interaction_result='FAILED' WHERE source_key='R1'");Map<String,String> q=new HashMap<>();q.put("view","PARCEL");q.put("warehouse","LAST_FAILED");Map<String,Object> r=rows(query.list("VERIFY",q,false)).get(0);assertEquals(2,number(unit(r,0),"quantity"));q.put("warehouse","FAILED");assertEquals(0,number(query.list("VERIFY",q,false),"total"));q.put("warehouse","ACCEPTED");assertEquals(1,number(query.list("VERIFY",q,false),"total"));}
    @Test void sharedActualWarehouseSummaryIsDeduplicatedAcrossSources(){mixed();Map<String,Object> w=map("return_sn","THKX_QUERY","warehouse_state","ACCEPTED","interaction",map("id",12,"result","FAILED","action","AFTERSALE_RETURN_QUERY"));f.db.update("UPDATE oms_return_query_row SET snapshot=?",encode(w));Map<String,Object> r=rows(list("PARCEL","TK101")).get(0);assertEquals(1,((List<?>)r.get("warehouse_documents")).size());assertEquals("FAILED",((Map<?,?>)r.get("latest_interaction")).get("result"));}
    @Test void finalReceiptDifferenceIsFilterableWithoutReducingPlan(){mixed();f.db.update("UPDATE oms_return_query_row SET receipt_difference=1 WHERE source_key='R1'");Map<String,String> q=new HashMap<>();q.put("view","PARCEL");q.put("warehouse","DIFFERENCE");assertEquals(2,number(unit(rows(query.list("VERIFY",q,false)).get(0),0),"quantity"));}
    @Test void newWarehouseFiltersAreValidatedBeforeProjection(){assertThrows(IllegalArgumentException.class,()->query.list("VERIFY",Collections.singletonMap("warehouse","BAD' OR 1=1"),false));verifyNoInteractions(projection);}
    @Test void directWarehouseEntryRefreshesItsReadProjectionBeforeReturningDetail(){row("VERIFY","DOCUMENT","THK_DIRECT","R1","REFUND",101,1,0,0,"件",0,0);when(projection.refresh("VERIFY")).thenAnswer(call->{f.db.update("UPDATE oms_return_query_row SET accepted_quantity=1,posted_quantity=1");return map("updating",false,"pending",0,"warning","");});Map<String,Object> detail=query.detail("VERIFY","DOCUMENT","THK_DIRECT",Collections.emptyMap());assertEquals(1,number(unit(detail,0),"posted_quantity"));verify(projection).refresh("VERIFY");}
    @Test void anUnindexedDocumentWaitsForIncrementalSyncInsteadOfShowingAnEmptyReturn(){when(projection.refresh("VERIFY")).thenReturn(map("updating",true,"pending",20,"warning",""));Map<String,Object> detail=query.detail("VERIFY","DOCUMENT","THK_NEW",Collections.emptyMap());assertEquals(true,detail.get("loading"));assertFalse(detail.containsKey("members"));}
    @Test void factsRequireAnActualCompanyScopedDocumentBeforeRemoteRead(){query.warehouse=mock(ReturnQueryClient.class);assertThrows(IllegalArgumentException.class,()->query.document("OTHER","THKX_QUERY","LINES",1,20));assertThrows(IllegalArgumentException.class,()->query.document("VERIFY","RSL_PRIVATE","SUMMARY",1,20));verifyNoInteractions(query.warehouse);row("VERIFY","DOCUMENT","THKX_QUERY","R1","REFUND",101,1,1,1,"件",0,0);when(query.warehouse.document(eq("VERIFY"),eq("THKX_QUERY"),eq("LINES"),eq(1),eq(20),anyString())).thenReturn(com.ruoyi.common.core.domain.R.ok(map("rows",Collections.emptyList(),"total",0)));assertEquals(0,number(query.document("VERIFY","THKX_QUERY","LINES",1,20),"total"));}
    @Test void lookupOneRefundKeepsCompleteMixedParcelAndHighlightsOnlyMatchingOwner(){mixed();Map<String,Object> result=list("PARCEL","TK101"),r=rows(result).get(0);assertEquals(1,number(result,"total"));assertEquals(2,number(r,"source_count"));assertEquals(1,number(r,"refund_count"));assertEquals(1,number(r,"exchange_count"));assertEquals(2,number(unit(r,0),"quantity"));Map<String,Object> detail=query.detail("VERIFY","PARCEL","P1",Collections.singletonMap("number","TK101"));assertEquals(1,number(detail,"matched_count"));assertEquals(2,((List<?>)detail.get("members")).size());}
    @Test void giftFilterSelectsWholeParcelWithoutDroppingPurchasedGoods(){mixed();f.db.update("UPDATE oms_return_query_row SET is_gift=1 WHERE source_key='R1'");Map<String,String> q=new HashMap<>();q.put("view","PARCEL");q.put("itemKind","GIFT");Map<String,Object> r=rows(query.list("VERIFY",q,false)).get(0);assertEquals(2,number(unit(r,0),"quantity"));assertEquals(1,number(r,"has_gift"));}
    @Test void sameWarehouseDocumentWithTwoPrivateSourcesIsOneRow(){row("VERIFY","DOCUMENT","THKX","R1","REFUND",101,1,1,1,"件",0,0);row("VERIFY","DOCUMENT","THKX","E1","EXCHANGE",201,1,1,1,"件",0,0);assertEquals(1,number(list("DOCUMENT",""),"total"));assertEquals(2,number(unit(rows(list("DOCUMENT","")).get(0),0),"posted_quantity"));}
    @Test void listProductsAggregateSamePhysicalSkuWithoutDuplicatingSourceRows(){mixed();Map<String,Object> r=rows(list("PARCEL","TK101")).get(0);assertEquals(1,number(r,"product_count"));List<Map<String,Object>> products=(List<Map<String,Object>>)r.get("products");assertEquals(2,number(products.get(0),"quantity"));assertEquals(2,((List<?>)r.get("members")).size());}
    @Test void physicalUnitsAreNeverRenderedAsOneMixedTotal(){row("VERIFY","PARCEL","P1","R1","REFUND",101,2,2,2,"件",0,0);row("VERIFY","PARCEL","P1","R2","REFUND",102,1,1,1,"套",1,0);Map<String,Object> r=rows(list("PARCEL","")).get(0);assertEquals(2,((List<?>)r.get("units")).size());assertEquals("DONE",r.get("stage"));}
    @Test void sharedPendingReceiptIsCountedOnceAndCannotBeComplete(){mixed();f.db.update("UPDATE oms_return_query_row SET pending_count=1");Map<String,Object> r=rows(list("PARCEL","")).get(0);assertEquals(1,number(r,"pending_count"));assertEquals("NEED_CHECK",r.get("stage"));}
    @Test void refundMoneyCannotSubstituteForPhysicalReceipt(){row("VERIFY","TASK","R1","R1","REFUND",101,2,0,0,"件",0,0);assertEquals("WAIT_RECEIVE",rows(list("TASK","")).get(0).get("stage"));}
    @Test void partialGoodReceiptRemainsPartialAndKeepsOutstandingQuantity(){row("VERIFY","TASK","R1","R1","REFUND",101,2,1,1,"件",0,0);Map<String,Object> r=rows(list("TASK","")).get(0);assertEquals("PARTIAL",r.get("stage"));assertEquals(1,number(unit(r,0),"remaining_quantity"));}
    @Test void confirmedReceiptAwaitingPostingIsItsOwnStage(){row("VERIFY","TASK","R1","R1","REFUND",101,2,2,1,"件",0,0);assertEquals("WAIT_POST",rows(list("TASK","")).get(0).get("stage"));}
    @Test void stoppingRemainingReturnDoesNotHideAlreadyReceivedButUnpostedGoods(){row("VERIFY","TASK","R1","R1","REFUND",101,3,1,0,"件",0,0);f.db.update("UPDATE oms_return_query_row SET active=0");assertEquals("WAIT_POST",rows(list("TASK","")).get(0).get("stage"));f.db.update("UPDATE oms_return_query_row SET posted_quantity=1");assertEquals("STOPPED",rows(list("TASK","")).get(0).get("stage"));}
    @Test void incompletePackageProjectionIsNotMarkedCompleted(){mixed();f.db.update("DELETE FROM oms_return_query_row WHERE owner_kind='EXCHANGE'");Map<String,Object> r=rows(list("PARCEL","")).get(0);assertEquals("NEED_CHECK",r.get("stage"));assertEquals(true,r.get("incomplete"));}
    @Test void fullPostedQuantityDoesNotHideOutstandingSourceReceiptReview(){f.shipped();long refund=f.convert(f.ingest(f.source(1,"5.00","WAIT_SELLER_AGREE")));Map<String,Object> shipment=f.db.queryForMap("SELECT sl.id,sl.shipment_id,s.shipment_sn FROM oms_order_shipment_line sl JOIN oms_order_shipment s ON s.id=sl.shipment_id");f.repo.insert("INSERT INTO oms_refund_return_plan(company_code,refund_id,shipment_line_id,shipment_id,shipment_sn,sku_sn,quantity,store_code,return_address,return_contact,package_ids,return_mode,state,accepted_quantity,posted_quantity) VALUES ('VERIFY',?,?,?,?,'A',5,'V','TEST','TEST','[]','RETURN','WAIT_REVIEW',5,5)",refund,shipment.get("id"),shipment.get("shipment_id"),shipment.get("shipment_sn"));ReturnQueryProjection p=new ReturnQueryProjection();p.repository=f.repo;List<Map<String,Object>> tasks=new ArrayList<>();org.springframework.test.util.ReflectionTestUtils.invokeMethod(p,"refundTasks","VERIFY",Collections.singleton(refund),tasks);assertEquals(1,tasks.size());assertEquals(1,number(tasks.get(0),"needs_check"));}
    @Test void companyIsolationAppliesToListNumberLookupAndDetail(){mixed();row("OTHER","PARCEL","P1","R2","REFUND",300,50,50,50,"件",0,0);indexNumber("OTHER","PARCEL","P1","REFUND",300,"OWNER","SECRET");assertEquals(0,number(list("PARCEL","SECRET"),"total"));assertThrows(IllegalArgumentException.class,()->query.detail("OTHER","PARCEL","MISSING",Collections.emptyMap()));assertEquals(2,number(unit(rows(list("PARCEL","TK101")).get(0),0),"quantity"));}
    @Test void mergeFiltersSeparateRefundOnlyExchangeOnlyAndMixed(){mixed();Map<String,String> q=new HashMap<>();q.put("view","PARCEL");q.put("merge","MIXED");assertEquals(1,number(query.list("VERIFY",q,false),"total"));q.put("merge","REFUND_MULTI");assertEquals(0,number(query.list("VERIFY",q,false),"total"));}
    @Test void invalidFiltersCannotReachProjectionOrInterpolateSql(){assertThrows(IllegalArgumentException.class,()->query.list("VERIFY",Collections.singletonMap("view","TASK' OR 1=1"),false));assertThrows(IllegalArgumentException.class,()->query.list("VERIFY",Collections.singletonMap("pageSize","501"),false));assertThrows(IllegalArgumentException.class,()->query.list("VERIFY",Collections.singletonMap("numberType","other"),false));verifyNoInteractions(projection);}
    @Test void numberInputIsBoundedAndDeduplicatesMultilineValues(){assertEquals(Arrays.asList("TK1","HH2"),ReturnQueryService.numbers("TK1\nHH2，TK1"));assertThrows(IllegalArgumentException.class,()->ReturnQueryService.numbers(String.join(",",Collections.nCopies(101,"A")).replace("A","X".repeat(129))));}
    @Test void sourceProjectionNeverPublishesPrivateSharedLedgerAsWarehouseDocument(){ReturnQueryProjection p=new ReturnQueryProjection();Map<String,Object> task=map("source_key","R:1","owner_kind","REFUND","owner_id",1,"quantity",1,"quantity_known",1,"accepted_quantity",0,"posted_quantity",0,"waived_quantity",0,"needs_check",0,"waybill","W","carrier","SF","active",1,"create_time","2026-10-25 00:00:00");Map<String,Object> w=map("part_key","REFUND:1","quantity",1,"accepted_quantity",0,"posted_quantity",0,"parcel_key","SHARED:1","parcel_sn","ASP1","return_sn","","pending_count",0,"expected_members",2,"source_created","2026-10-25 00:00:00","parcel_created","2026-10-25 00:00:00");List<Map<String,Object>> rows=new ArrayList<>();p.project("VERIFY",task,Collections.singletonList(w),rows);assertEquals(2,rows.size());assertTrue(rows.stream().noneMatch(r->"DOCUMENT".equals(r.get("view_kind"))));}
    @Test void rearrangingStoppedRemainderDoesNotDoubleCountPackageIntent(){ReturnQueryProjection p=new ReturnQueryProjection();Map<String,Object> task=map("source_key","R:1","quantity",3,"quantity_known",1,"active",1,"needs_check",0,"waived_quantity",0,"waybill","W");Map<String,Object> first=map("part_key","R:old","quantity",3,"cancelled_quantity",2,"accepted_quantity",1,"posted_quantity",1,"cancel_state","CONFIRMED","parcel_key","P1","return_sn","THK_OLD","expected_members",1,"pending_count",0),second=map("part_key","R:new","quantity",2,"cancelled_quantity",0,"accepted_quantity",0,"posted_quantity",0,"cancel_state","NONE","parcel_key","P1","return_sn","THK_NEW","expected_members",1,"pending_count",0);List<Map<String,Object>> rows=new ArrayList<>();p.project("VERIFY",task,Arrays.asList(first,second),rows);assertEquals(3,rows.stream().filter(r->"PARCEL".equals(r.get("view_kind"))).mapToLong(r->number(r,"quantity")).sum());assertEquals(5,rows.stream().filter(r->"DOCUMENT".equals(r.get("view_kind"))).mapToLong(r->number(r,"quantity")).sum());assertEquals(2,rows.stream().filter(r->"DOCUMENT".equals(r.get("view_kind"))).count());}
}
